'use client';

import React, { useState } from 'react';
import Image from 'next/image';
import Link from 'next/link';
import { ChevronRight } from 'lucide-react';

const EMIcalculator = () => {
    return (
        <div className="relative min-h-screen bg-[#F4F5F7] font-sans">
            {/* 1. Purple Background Hero Block (Absolute) */}
            <div className="absolute top-0 left-0 right-0 h-[550px] bg-gradient-to-r from-[#3e2393] to-[#5b36c4] rounded-b-[3rem] md:rounded-b-[5rem] z-0 overflow-hidden">
                {/* Decorative Circles/Blobs */}
                <div className="absolute top-[-50px] right-[-50px] w-64 h-64 bg-white opacity-5 rounded-full blur-3xl"></div>
                <div className="absolute bottom-[-50px] left-[-50px] w-80 h-80 bg-purple-400 opacity-10 rounded-full blur-3xl"></div>
            </div>

            {/* Main Container */}
            <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-40 pb-24 overflow-visible flex justify-center">
                <div className="w-full max-w-6xl z-30 rounded-3xl">
                    <PropertyFormCard />
                </div>
            </div>
        </div>
    );
};

const PropertyFormCard = () => {

    const [lookingTo, setLookingTo] = useState('Sell');
    const [city, setCity] = useState('');
    const [project, setProject] = useState('');
    const [locality, setLocality] = useState('');
    const [propertyType, setPropertyType] = useState('Apartment');
    const [bedrooms, setBedrooms] = useState('1');
    const [area, setArea] = useState('');

    const propertyTypes = ['Apartment', 'Independent Floor', 'Independent House', 'Villa'];
    const bedroomOptions = ['1', '2', '3', '4', '5+'];

    return (
        <div className="bg-white rounded-3xl shadow-xl border border-gray-100/50 flex flex-col max-h-[90vh]">

            {/* Header */}
            <div className="p-8 border-b border-gray-100 bg-white z-10 sticky top-0 rounded-t-3xl">
                <h3 className="text-2xl font-bold text-gray-900">Property Value Calculator</h3>
                <p className="text-gray-500 mt-1 text-sm">Let's calculate sale or rent value in seconds</p>
            </div>

            {/* Scrollable Content */}
            <div className="p-8 space-y-8 overflow-y-auto custom-scrollbar">

                {/* Looking To */}
                <div className="space-y-3">
                    <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Looking to <span className="text-red-500">*</span></label>
                    <div className="flex gap-4">
                        {['Sell', 'Rent'].map((option) => (
                            <button
                                key={option}
                                onClick={() => setLookingTo(option)}
                                className={`px-8 py-3 rounded-xl text-sm font-bold transition-all border ${lookingTo === option ? 'bg-purple-50 border-[#3e2393] text-[#3e2393]' : 'bg-white border-gray-200 text-gray-600 hover:border-gray-300'}`}
                            >
                                {option}
                            </button>
                        ))}
                    </div>
                </div>

                {/* City */}
                <div className="space-y-3">
                    <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">City <span className="text-red-500">*</span></label>
                    <input
                        type="text"
                        value={city}
                        onChange={(e) => setCity(e.target.value)}
                        placeholder="Enter City"
                        className="w-full px-4 py-3 rounded-xl border border-gray-300 focus:outline-none focus:ring-2 focus:ring-[#3e2393] focus:border-transparent transition-all placeholder-gray-400 font-medium"
                    />
                </div>

                {/* Project */}
                <div className="space-y-3">
                    <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Project</label>
                    <input
                        type="text"
                        value={project}
                        onChange={(e) => setProject(e.target.value)}
                        placeholder="Enter Project Name"
                        className="w-full px-4 py-3 rounded-xl border border-gray-300 focus:outline-none focus:ring-2 focus:ring-[#3e2393] focus:border-transparent transition-all placeholder-gray-400 font-medium"
                    />
                </div>

                {/* Locality */}
                <div className="space-y-3">
                    <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Locality <span className="text-red-500">*</span></label>
                    <input
                        type="text"
                        value={locality}
                        onChange={(e) => setLocality(e.target.value)}
                        placeholder="Enter Locality"
                        className="w-full px-4 py-3 rounded-xl border border-gray-300 focus:outline-none focus:ring-2 focus:ring-[#3e2393] focus:border-transparent transition-all placeholder-gray-400 font-medium"
                    />
                </div>

                {/* Property Type */}
                <div className="space-y-3">
                    <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Property Type <span className="text-red-500">*</span></label>
                    <div className="flex flex-wrap gap-3">
                        {propertyTypes.map((type) => (
                            <button
                                key={type}
                                onClick={() => setPropertyType(type)}
                                className={`px-4 py-2.5 rounded-lg border text-sm font-medium transition-all ${propertyType === type ? 'bg-purple-50 border-[#3e2393] text-[#3e2393]' : 'bg-white border-gray-200 text-gray-600 hover:border-gray-300'}`}
                            >
                                {type}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Bedrooms */}
                <div className="space-y-3">
                    <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Bedrooms <span className="text-red-500">*</span></label>
                    <div className="flex flex-wrap gap-3">
                        {bedroomOptions.map((opt) => (
                            <button
                                key={opt}
                                onClick={() => setBedrooms(opt)}
                                className={`w-12 h-12 flex items-center justify-center rounded-xl border text-sm font-bold transition-all ${bedrooms === opt ? 'bg-purple-50 border-[#3e2393] text-[#3e2393]' : 'bg-white border-gray-200 text-gray-600 hover:border-gray-300'}`}
                            >
                                {opt}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Area */}
                <div className="space-y-3">
                    <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Area (sq.ft) <span className="text-red-500">*</span></label>
                    <input
                        type="number"
                        value={area}
                        onChange={(e) => setArea(e.target.value)}
                        placeholder="0"
                        className="w-full px-4 py-3 rounded-xl border border-gray-300 focus:outline-none focus:ring-2 focus:ring-[#3e2393] focus:border-transparent transition-all placeholder-gray-400 font-medium"
                    />
                </div>

            </div>

            {/* Footer / Submit */}
            <div className="p-8 border-t border-gray-100 bg-white sticky bottom-0 rounded-b-3xl z-10">
                <button className="w-full bg-[#172747] hover:bg-[#0f1b33] text-white font-bold py-4 rounded-xl shadow-lg hover:shadow-xl transition-all transform hover:-translate-y-0.5 active:translate-y-0 text-lg flex items-center justify-center gap-2">
                    Calculate Value <ChevronRight size={20} strokeWidth={2.5} />
                </button>
            </div>

        </div>
    );
}

export default EMIcalculator;
